mapper.insert:
insert into gw_return_application(assignment_id,student_id,workstation_id,source_type,status,reason,photo_urls,photo_upload_time,student_cleared,create_time)
values(#{assignmentId},#{studentId},#{workstationId},#{sourceType},#{status},#{reason},#{photoUrls},
       if(#{photoUrls} is null,null,now()),if(#{photoUrls} is null,0,1),now())

insert into gw_audit_log(business_type,business_id,action,operator_id,before_data,after_data,reason,create_time)
values('RETURN',#{returnId},#{action},#{operatorId},
       if(#{beforeStatus} is null,null,json_object('status',#{beforeStatus})),
       if(#{afterStatus} is null,null,json_object('status',#{afterStatus})),#{reason},now())
